def experiment(inputs):
    import random
    params = inputs.get('parameters', {'feedback_intensity': 0.5})
    seeds = inputs.get('seeds', [13, 71, 43, 101])
    results = []
    for seed in seeds:
        rng = random.Random(seed)
        val = rng.gauss(0, 1)
        for _ in range(10):
            val = max(-100.0, min(100.0, val * (1.0 + params['feedback_intensity'] * rng.gauss(0, 0.1))))
        results.append(val)
    spread = max(results) - min(results)
    return {"measurements": {"measurement_validity": [True], "distributional_spread": [spread]}}

def experiment(inputs):
    import random
    params = inputs.get('parameters', {'feedback_intensity': 0.5})
    seeds = inputs.get('seeds', [13, 71, 43, 101])
    res = []
    for s in seeds:
        rng = random.Random(s)
        val = rng.gauss(0, 1)
        for _ in range(10):
            delta = params['feedback_intensity'] * (val if val > 0 else -val)
            val = max(-100.0, min(100.0, val + delta))
        res.append(val)
    return {'measurements': {'distributional_spread': res}}
